BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "Test" (
	"Id"	INTEGER,
	"Step"	INTEGER,
	"Method"	TEXT NOT NULL,
	"Uri"	TEXT NOT NULL,
	"JsonGetParameters"	TEXT,
	"JsonPostParameters"	TEXT,
	"JsonConnectedUser"	TEXT,
	"ExpectedResponseCode"	TEXT NOT NULL,
	"Query"	TEXT,
	"QueryExpectedResponse"	TEXT,
	PRIMARY KEY("Id")
);
FROM Individual i
JOIN Member m ON m.Id = i.Id
WHERE i.Id = 16','[{"Email":"user@myclub.foo","FirstName":"Simple","LastName":"Member","Password":"55cd6eeb8e4cd1ee8384ade7564bf65f90706a631dc04d827b7585309fe6423f"}]');
FROM Individual i
JOIN Member m ON m.Id = i.Id
WHERE i.Id = 16','[{"Id":16,"Email":"","Password":null}]');
Set 
	Token = "0123456789abcdefaaa", 
	TokenCreatedAt = CURRENT_TIMESTAMP 
Where Id = 16','[]');
COMMIT;
